#Requires -Version 7.0
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$c=Get-Content "$root\config\catalog.json" -Raw|ConvertFrom-Json;$p=Get-Content "$root\config\profiles.json" -Raw|ConvertFrom-Json;$b=Get-Content "$root\config\bookmarks.json" -Raw|ConvertFrom-Json;$errors=@();$seen=@{}
foreach($i in $c.items){foreach($f in @('id','name','category','destination','sourceType','installPolicy')){if(-not $i.PSObject.Properties.Name.Contains($f)-or[string]::IsNullOrWhiteSpace([string]$i.$f)){$errors+="$($i.id): missing $f"}};if($seen[$i.id]){$errors+="Duplicate id: $($i.id)"}else{$seen[$i.id]=$true};if($i.destination -match '(^|\\)\.\.(\\|$)'){$errors+="$($i.id): path traversal"};if($i.sourceType -ne 'InteractiveImport' -and -not $i.allowedHosts){$errors+="$($i.id): no allowedHosts"}}
if($errors){$errors|%{Write-Error $_};exit 1};Write-Host "Validation passed: $($c.items.Count) catalog items, $($p.profiles.Count) profiles, $($b.offlineResources.Count) offline resources."
